# src/montecarlo/two_body_decay.py
#
# Generic two-body decays (parent -> daughter1 daughter2) of the particles generated by
# init_beam, restricted to the (x, z) plane. The channels are defined in src/constants.py
#
# Units: MeV, mm, rad, c = 1.

import numpy as np
import pandas as pd

from src.constants import DecayChannel
from src.montecarlo.tracks import track_table


# Lorentz boost in the (x, z) plane of the 4-momenta (E, px, pz) by the velocity (betax, betaz)
def boost_2d(E, px, pz, betax, betaz):

    beta = np.sqrt(betax**2 + betaz**2)
    beta2 = beta**2
    gamma = 1 / np.sqrt(1 - beta2)
    bp = betax * px + betaz * pz
    coef = (gamma - 1) / np.where(beta2 > 0, beta2, 1) * bp + gamma * E

    return gamma * (E + bp), px + coef * betax, pz + coef * betaz


# Decays parents of mass M with lab 4-momenta (E, px, pz) into two daughters of masses m1, m2.
# The decay is isotropic in the (x, z) plane of the parent rest frame.
# Returns: (E1, px1, pz1), (E2, px2, pz2) in the lab frame

def two_body_decay_2d(E, px, pz, M, m1, m2, rng):

    if M <= m1 + m2:
        raise ValueError(f"Decay not allowed: M = {M} <= m1 + m2 = {m1 + m2}")

    # 1. Daughter momentum in the parent rest frame
    p_star = np.sqrt((M**2 - (m1 + m2)**2) * (M**2 - (m1 - m2)**2)) / (2 * M)
    alpha = rng.uniform(0, 2 * np.pi, len(E))
    px_star = p_star * np.sin(alpha)
    pz_star = p_star * np.cos(alpha)

    # 2. Boost to the lab frame (back to back in the rest frame)
    betax, betaz = px / E, pz / E
    daughter1 = boost_2d(np.hypot(p_star, m1),  px_star,  pz_star, betax, betaz)
    daughter2 = boost_2d(np.hypot(p_star, m2), -px_star, -pz_star, betax, betaz)

    return daughter1, daughter2


# Decays every parent in the track table df_parents through the given channel.
# df_parents: track DataFrame of the parents (output of Initial_Beam.generate)
# channel: DecayChannel to apply
# seed: seed of the random generator, for reproducibility (None = random)
# Returns: track DataFrame of the daughters, two rows per event, starting at the decay vertex

def decay(df_parents, channel: DecayChannel, seed=None):

    rng = np.random.default_rng(seed)
    parent = channel.parent
    daughter1, daughter2 = channel.daughters

    if not (df_parents["particle"] == parent.name).all():
        raise ValueError(f"df_parents must contain only {parent.name}")

    E = df_parents["E0"].to_numpy()
    px = df_parents["px0"].to_numpy()
    pz = df_parents["pz0"].to_numpy()
    p = df_parents["p0"].to_numpy()

    # 1. Flight distance in the lab, L ~ Exp(beta*gamma*ctau), and decay vertex
    if np.isinf(parent.ctau):
        raise ValueError(f"{parent.name} is stable (ctau = inf)")
    L = rng.exponential(p / parent.mass * parent.ctau)
    x_v = df_parents["x0"].to_numpy() + L * px / p
    z_v = df_parents["z0"].to_numpy() + L * pz / p

    # 2. Decay kinematics
    (_, px1, pz1), (_, px2, pz2) = two_body_decay_2d(E, px, pz, parent.mass, daughter1.mass, daughter2.mass, rng)

    # 3. Track tables of the daughters, grouped by event
    event_id = df_parents["event_id"].to_numpy()
    df = pd.concat([
        track_table(event_id, daughter1, x_v, z_v, px1, pz1),
        track_table(event_id, daughter2, x_v, z_v, px2, pz2),
    ])

    return df.sort_values("event_id", kind="stable").reset_index(drop=True)


# Invariant mass of all the tracks of each event, in MeV
# df: track DataFrame (MC truth or fitted tracks)
# Returns: Series indexed by event_id

def invariant_mass(df):

    tot = df.groupby("event_id")[["E0", "px0", "pz0"]].sum()

    return np.sqrt(tot["E0"]**2 - tot["px0"]**2 - tot["pz0"]**2)
